Get Collection Mappings.code:
// Fetch the mappings in a collection (e.g. a programme's indicator mappings).
getMappings(
  // 1) The owning organization (or user) id.
  'MSFOCG',
  // 2) The collection (or source) id.
  $.data.collectionId,
  // 3) Options: owner/repository type, version and query params.
  {
    ownerType: 'orgs', // 'orgs' or 'users'
    repository: 'collections', // 'collections' or 'sources'
    version: 'HEAD', // or a released version, e.g. 'v1.2'
    page: 1,
    limit: 200,
    verbose: false,
  }
);

Search Concepts In Source.code:
// Search concepts in a source, e.g. CIEL, by free-text keyword.
get(
  // 1) Path relative to the OCL host URL.
  'orgs/CIEL/sources/CIEL/concepts/',
  // 2) Query parameters.
  {
    q: 'malaria', // free-text search
    limit: 25,
    page: 1,
    verbose: true, // include names and descriptions
    includeRetired: false,
  }
);

Get Concept By ID.code:
// Fetch one concept (names, datatype, class) from a source.
get(
  // 1) orgs/{org}/sources/{source}/concepts/{concept}/
  `orgs/CIEL/sources/CIEL/concepts/${$.data.conceptId}/`,
  // 2) Query parameters.
  { verbose: true }
);

Get Mappings For Concept.code:
// List the mappings that start from one concept, e.g. CIEL -> ICD-10.
get(
  `orgs/CIEL/sources/CIEL/concepts/${$.data.conceptId}/mappings/`,
  {
    limit: 100,
    includeRetired: false,
  }
);

Get Concepts Updated Since.code:
// Pull only the concepts changed since the last sync.
get(
  `orgs/${$.data.orgId}/sources/${$.data.sourceId}/concepts/`,
  {
    // ISO date of the last successful sync (e.g. saved in state or a collection).
    updatedSince: $.data.lastSync || '2026-01-01',
    limit: 200,
    page: 1,
    verbose: true,
  }
);

Cascade Concept Hierarchy.code:
// Get a concept plus everything it links to (answers, set members).
get(
  `orgs/CIEL/sources/CIEL/concepts/${$.data.conceptId}/$cascade/`,
  {
    cascadeHierarchy: true, // follow parent/child links
    cascadeMappings: true, // follow mappings
    cascadeLevels: 1, // how many levels deep
    mapTypes: 'Q-AND-A,CONCEPT-SET', // only these map types
  }
);

List Source Versions.code:
// List the released versions of a source.
get(
  `orgs/${$.data.orgId}/sources/${$.data.sourceId}/versions/`,
  { limit: 20 }
);

List Concepts In Collection.code:
// List the concepts in a released collection version (e.g. a facility form value set).
get(
  // orgs/{org}/collections/{collection}/{version}/concepts/
  `orgs/${$.data.orgId}/collections/${$.data.collectionId}/v1.0/concepts/`,
  {
    limit: 100,
    page: 1,
    verbose: true,
  }
);

List Organization Sources.code:
// List the sources (terminologies) an organization publishes.
get(
  `orgs/${$.data.orgId}/sources/`,
  { limit: 50 }
);
